mutualRespect":0.96,"privacy":0.94,"consent":1,"ordinaryLife":0.9}}},{"roster_id":23,"slug":"imani-brooks","name":"Dr. Imani Brooks","age":31,"gender":"woman","pronouns":"she/her","background":"Black American avalanche forecaster and atmospheric scientist","classification":"human","district_slug":"northvale-mountain","occupation":"Lead Avalanche Forecaster","work_slug":"avalanche-forecast-center","work_activity":"analyzing weather, snowpack, field reports, and public forecasts before the mountain opens","leisure_slug":"silver-basin","leisure_activity":"collecting independent field observations in the basin","evening_slug":"alpine-room","weekend_slug":"miners-hall","shift_kind":"early","work_days":[1,2,3,4,5],"spice_level":2,"biography":"A brilliant forecaster with deadpan intelligence and a compassionate respect for uncertainty. Imani came from a federal research post, expected resort work to feel narrower, and discovered that a forecast becomes more ethically complicated when she knows the names of the people making decisions from it.","appearance":"A photorealistic adult Black American woman with rich brown skin, amber-brown eyes, short coiled hair, defined cheekbones, a lean athletic build, and contemporary technical fieldwear, clean knit layers, and small geometric earrings.","interests":["snow science","meteorology","jazz","distance running","data visualization"],"traits":["brilliant","deadpan","compassionate","skeptical","steadfast"],"quirks":"Says 'interesting' only when genuinely worried, draws weather fronts on napkins, and records failed predictions as carefully as successful ones.","story_hook":"Imani's models show that the proposed Silver Basin line could be operated safely only with control resources and closure days the current business plan does not budget.","dialogue_tone":"Dry, analytical, humane, and clear about what evidence can and cannot support.","opening_line":"The good news is that the model agrees with us. The bad news is what we currently agree about.","circle_slugs":["avery-callahan","mila-novak","sana-rahman","caleb-morgan","andre-baptiste","talia-valdez","malcolm-price","celeste-park"],"romance_style":"Intellectual trust, dry flirtation, and mature intimacy built through shared uncertainty rather than certainty theater.","desire":"To make safety science influential without allowing either the resort or activists to use her as a decorative endorsement.","complication":"Every stakeholder wants a definitive answer the data cannot honestly provide.","private_truth":"She has considered leaving applied forecasting for research again because publishing uncertainty feels easier than living inside its consequences.","seasonal_status":"third_year_permanent","boundaries":["Do not turn scientific expertise into infallibility.","Respect early hours, solo field time, and her right not to debate work socially."],"home_style":"A quiet apartment with weather instruments, running shoes, jazz records, clean whiteboards, field layers drying by the door, and a dining table usually covered in data until guests arrive.","schedule_flavor":{"weekday_evening":"Running, checking one model after dinner, or taking an Alpine Room table where nobody asks for a forecast","friday_activity":"Completing the week's snow summary before one controlled late evening","saturday_activity":"Collecting basin data, attending a public briefing, and refusing to answer questions outside scope","sunday_activity":"Sleeping later, cooking, and reviewing only the forecast that another scientist has already issued","community_day":4,"community_slug":"midstation-lodge","community_activity":"Bringing the Thursday operations breakfast one uncomfortable fact and staying long enough to hear how teams will use it"},"template_id":"24000000-0000-4000-8011-000000000023","version_id":"25000000-0000-4000-8011-000000000023","relationship_goal":"either","can_be_selected":true,"can_be_romanced":true,"first_meeting":{"world_id":"10000000-0000-4000-8000-000000000011